// ============================================================
// Module : alu
// Project: RV32I Single-Cycle CPU
// Desc   : Full 32-bit ALU for all RV32I instructions.
//
// alu_ctrl encoding (generated by alu_control.v):
//   4'b0000  ADD   rd = a + b
//   4'b0001  SUB   rd = a - b
//   4'b0010  AND   rd = a & b
//   4'b0011  OR    rd = a | b
//   4'b0100  XOR   rd = a ^ b
//   4'b0101  SLL   rd = a << b[4:0]
//   4'b0110  SRL   rd = a >> b[4:0]  (logical)
//   4'b0111  SRA   rd = a >>> b[4:0] (arithmetic)
//   4'b1000  SLT   rd = (signed a < signed b) ? 1 : 0
//   4'b1001  SLTU  rd = (unsigned a < unsigned b) ? 1 : 0
//   4'b1010  LUI   rd = b  (pass B through — used for LUI)
//   4'b1011  AUIPC rd = a + b  (same as ADD, PC passed as a)
// ============================================================
`timescale 1ns/1ps

module alu (
    input  wire [31:0] a,          // operand A  (always rs1_data or PC)
    input  wire [31:0] b,          // operand B  (rs2_data or immediate)
    input  wire [ 3:0] alu_ctrl,   // operation select
    output reg  [31:0] result,     // ALU result
    output wire        zero        // result == 0  (used by BEQ / BNE)
);

    assign zero = (result == 32'b0);

    // Signed views of operands (needed for SLT, SRA)
    wire signed [31:0] a_s = $signed(a);
    wire signed [31:0] b_s = $signed(b);

    always @(*) begin
        case (alu_ctrl)
            4'b0000: result = a + b;                          // ADD / ADDI / LOAD / STORE / AUIPC / JAL
            4'b0001: result = a - b;                          // SUB / all branches (compare via zero flag)
            4'b0010: result = a & b;                          // AND / ANDI
            4'b0011: result = a | b;                          // OR  / ORI
            4'b0100: result = a ^ b;                          // XOR / XORI
            4'b0101: result = a << b[4:0];                    // SLL / SLLI
            4'b0110: result = a >> b[4:0];                    // SRL / SRLI  (zero-fill)
            4'b0111: result = a_s >>> b[4:0];                 // SRA / SRAI  (sign-fill)
            4'b1000: result = (a_s < b_s)  ? 32'd1 : 32'd0;  // SLT  / SLTI
            4'b1001: result = (a  < b)     ? 32'd1 : 32'd0;  // SLTU / SLTIU
            4'b1010: result = b;                              // LUI  (pass upper-imm through)
            4'b1011: result = a + b;                          // AUIPC (PC + upper-imm)
            default: result = 32'b0;
        endcase
    end

endmodule
